def base_string_uri(uri: str, host: str=None) ->str:
    if not isinstance(uri, str):
        raise ValueError('uri must be a string')
    if not uri or uri.strip() == '':
        raise ValueError('uri is empty')
    uri = uri.strip()
    parsed = urlparse.urlparse(uri)
    scheme = parsed.scheme
    if not scheme:
        raise ValueError('uri has no scheme')
    scheme = scheme.lower()
    netloc = parsed.netloc
    path = parsed.path
    if host is not None:
        netloc = host
    if not netloc:
        raise ValueError('uri has no host')
    if '@' in netloc:
        netloc = netloc.split('@', 1)[1]
    if netloc.startswith('['):
        bracket_end = netloc.find(']')
        if bracket_end == -1:
            raise ValueError('invalid IPv6 address')
        host_part = netloc[:bracket_end + 1]
        rest = netloc[bracket_end + 1:]
        if rest.startswith(':'):
            port_str = rest[1:]
        else:
            port_str = None
    elif ':' in netloc:
        parts = netloc.split(':')
        if len(parts) > 2:
            raise ValueError('invalid host:port')
        host_part = parts[0]
        port_str = parts[1]
    else:
        host_part = netloc
        port_str = None
    if not host_part:
        raise ValueError('uri has no host')
    default_ports = {'http': '80', 'https': '443'}
    if port_str is not None:
        if port_str == '':
            port_str = None
        else:
            try:
                port_num = int(port_str)
            except ValueError:
                raise ValueError('invalid port: ' + port_str)
            if port_num <= 0 or port_num > 65535:
                raise ValueError('invalid port number: ' + str(port_num))
            if default_ports.get(scheme) == port_str:
                port_str = None
    host_part = host_part.lower()
    if ' ' in host_part:
        host_part = urlparse.quote(host_part, safe='[].:')
    if port_str is not None:
        netloc = host_part + ':' + port_str
    else:
        netloc = host_part
    if not path:
        path = '/'
    path = urlparse.quote(urlparse.unquote(path), safe='/-._~!$&\'()*+,;=:@%')
    result = scheme + '://' + netloc + path
    return result
